-- Load facilities.DimFacility (dimension, SCD type 1).
-- One stored procedure per destination table (DE Policy v2, 5.3).
-- Generated by `python -m fde render` from models/gold/facilities/DimFacility.yml. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [facilities].[LoadDimFacility]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now datetime2(6) = SYSUTCDATETIME();
    DECLARE @MaxKey bigint = (SELECT COALESCE(MAX([DimFacility_SK]), 0)
                              FROM [facilities].[DimFacility] WHERE [DimFacility_SK] > 0);

    MERGE [facilities].[DimFacility] AS target
    USING (
        SELECT
            CAST(s.[Facility_BK] AS varchar(20)) AS [Facility_BK],
            CAST(s.[FacilityName] AS varchar(100)) AS [FacilityName],
            CAST(s.[FacilityOtherNames] AS varchar(400)) AS [FacilityOtherNames],
            CAST(s.[SubSiteName] AS varchar(120)) AS [SubSiteName],
            CAST(s.[SubSiteOtherNames] AS varchar(200)) AS [SubSiteOtherNames],
            CAST(s.[FacilityType] AS varchar(50)) AS [FacilityType],
            CAST(s.[PrimaryCommodity] AS varchar(50)) AS [PrimaryCommodity],
            CAST(s.[CommoditiesProducts] AS varchar(400)) AS [CommoditiesProducts],
            CAST(s.[FacilityEquipment] AS varchar(800)) AS [FacilityEquipment],
            CAST(s.[ActivityStatus] AS varchar(50)) AS [ActivityStatus],
            CAST(s.[Country] AS varchar(60)) AS [Country],
            CAST(s.[GadmLevel0Code] AS varchar(10)) AS [GadmLevel0Code],
            CAST(s.[GadmLevel1Code] AS varchar(80)) AS [GadmLevel1Code],
            CAST(s.[GadmLevel2Code] AS varchar(200)) AS [GadmLevel2Code],
            CAST(s.[GadmLevel3Code] AS varchar(300)) AS [GadmLevel3Code],
            CAST(s.[GadmLevel4Code] AS varchar(400)) AS [GadmLevel4Code],
            CAST(s.[LocationGeometry] AS varchar(2000)) AS [LocationGeometry],
            CAST(s.[Comment] AS varchar(1000)) AS [Comment],
            CAST(s.[SurfaceAreaSquareKilometers] AS decimal(18,4)) AS [SurfaceAreaSquareKilometers],
            CAST(s.[ConcessionAreaSquareKilometers] AS decimal(18,4)) AS [ConcessionAreaSquareKilometers],
            CAST(s.[ProductionStartYear] AS int) AS [ProductionStartYear],
            CAST(s.[ProductionEndYear] AS int) AS [ProductionEndYear],
            CAST(s.[ActivityStatusYear] AS int) AS [ActivityStatusYear],
            @MaxKey + ROW_NUMBER() OVER (ORDER BY s.[Facility_BK]) AS [NewKey]
        FROM [stage].[DimFacilitySource] AS s
    ) AS source
    ON target.[Facility_BK] = source.[Facility_BK]
    WHEN MATCHED AND (
        (target.[FacilityName] <> source.[FacilityName] OR (target.[FacilityName] IS NULL AND source.[FacilityName] IS NOT NULL) OR (target.[FacilityName] IS NOT NULL AND source.[FacilityName] IS NULL))
        OR (target.[FacilityOtherNames] <> source.[FacilityOtherNames] OR (target.[FacilityOtherNames] IS NULL AND source.[FacilityOtherNames] IS NOT NULL) OR (target.[FacilityOtherNames] IS NOT NULL AND source.[FacilityOtherNames] IS NULL))
        OR (target.[SubSiteName] <> source.[SubSiteName] OR (target.[SubSiteName] IS NULL AND source.[SubSiteName] IS NOT NULL) OR (target.[SubSiteName] IS NOT NULL AND source.[SubSiteName] IS NULL))
        OR (target.[SubSiteOtherNames] <> source.[SubSiteOtherNames] OR (target.[SubSiteOtherNames] IS NULL AND source.[SubSiteOtherNames] IS NOT NULL) OR (target.[SubSiteOtherNames] IS NOT NULL AND source.[SubSiteOtherNames] IS NULL))
        OR (target.[FacilityType] <> source.[FacilityType] OR (target.[FacilityType] IS NULL AND source.[FacilityType] IS NOT NULL) OR (target.[FacilityType] IS NOT NULL AND source.[FacilityType] IS NULL))
        OR (target.[PrimaryCommodity] <> source.[PrimaryCommodity] OR (target.[PrimaryCommodity] IS NULL AND source.[PrimaryCommodity] IS NOT NULL) OR (target.[PrimaryCommodity] IS NOT NULL AND source.[PrimaryCommodity] IS NULL))
        OR (target.[CommoditiesProducts] <> source.[CommoditiesProducts] OR (target.[CommoditiesProducts] IS NULL AND source.[CommoditiesProducts] IS NOT NULL) OR (target.[CommoditiesProducts] IS NOT NULL AND source.[CommoditiesProducts] IS NULL))
        OR (target.[FacilityEquipment] <> source.[FacilityEquipment] OR (target.[FacilityEquipment] IS NULL AND source.[FacilityEquipment] IS NOT NULL) OR (target.[FacilityEquipment] IS NOT NULL AND source.[FacilityEquipment] IS NULL))
        OR (target.[ActivityStatus] <> source.[ActivityStatus] OR (target.[ActivityStatus] IS NULL AND source.[ActivityStatus] IS NOT NULL) OR (target.[ActivityStatus] IS NOT NULL AND source.[ActivityStatus] IS NULL))
        OR (target.[Country] <> source.[Country] OR (target.[Country] IS NULL AND source.[Country] IS NOT NULL) OR (target.[Country] IS NOT NULL AND source.[Country] IS NULL))
        OR (target.[GadmLevel0Code] <> source.[GadmLevel0Code] OR (target.[GadmLevel0Code] IS NULL AND source.[GadmLevel0Code] IS NOT NULL) OR (target.[GadmLevel0Code] IS NOT NULL AND source.[GadmLevel0Code] IS NULL))
        OR (target.[GadmLevel1Code] <> source.[GadmLevel1Code] OR (target.[GadmLevel1Code] IS NULL AND source.[GadmLevel1Code] IS NOT NULL) OR (target.[GadmLevel1Code] IS NOT NULL AND source.[GadmLevel1Code] IS NULL))
        OR (target.[GadmLevel2Code] <> source.[GadmLevel2Code] OR (target.[GadmLevel2Code] IS NULL AND source.[GadmLevel2Code] IS NOT NULL) OR (target.[GadmLevel2Code] IS NOT NULL AND source.[GadmLevel2Code] IS NULL))
        OR (target.[GadmLevel3Code] <> source.[GadmLevel3Code] OR (target.[GadmLevel3Code] IS NULL AND source.[GadmLevel3Code] IS NOT NULL) OR (target.[GadmLevel3Code] IS NOT NULL AND source.[GadmLevel3Code] IS NULL))
        OR (target.[GadmLevel4Code] <> source.[GadmLevel4Code] OR (target.[GadmLevel4Code] IS NULL AND source.[GadmLevel4Code] IS NOT NULL) OR (target.[GadmLevel4Code] IS NOT NULL AND source.[GadmLevel4Code] IS NULL))
        OR (target.[LocationGeometry] <> source.[LocationGeometry] OR (target.[LocationGeometry] IS NULL AND source.[LocationGeometry] IS NOT NULL) OR (target.[LocationGeometry] IS NOT NULL AND source.[LocationGeometry] IS NULL))
        OR (target.[Comment] <> source.[Comment] OR (target.[Comment] IS NULL AND source.[Comment] IS NOT NULL) OR (target.[Comment] IS NOT NULL AND source.[Comment] IS NULL))
        OR (target.[SurfaceAreaSquareKilometers] <> source.[SurfaceAreaSquareKilometers] OR (target.[SurfaceAreaSquareKilometers] IS NULL AND source.[SurfaceAreaSquareKilometers] IS NOT NULL) OR (target.[SurfaceAreaSquareKilometers] IS NOT NULL AND source.[SurfaceAreaSquareKilometers] IS NULL))
        OR (target.[ConcessionAreaSquareKilometers] <> source.[ConcessionAreaSquareKilometers] OR (target.[ConcessionAreaSquareKilometers] IS NULL AND source.[ConcessionAreaSquareKilometers] IS NOT NULL) OR (target.[ConcessionAreaSquareKilometers] IS NOT NULL AND source.[ConcessionAreaSquareKilometers] IS NULL))
        OR (target.[ProductionStartYear] <> source.[ProductionStartYear] OR (target.[ProductionStartYear] IS NULL AND source.[ProductionStartYear] IS NOT NULL) OR (target.[ProductionStartYear] IS NOT NULL AND source.[ProductionStartYear] IS NULL))
        OR (target.[ProductionEndYear] <> source.[ProductionEndYear] OR (target.[ProductionEndYear] IS NULL AND source.[ProductionEndYear] IS NOT NULL) OR (target.[ProductionEndYear] IS NOT NULL AND source.[ProductionEndYear] IS NULL))
        OR (target.[ActivityStatusYear] <> source.[ActivityStatusYear] OR (target.[ActivityStatusYear] IS NULL AND source.[ActivityStatusYear] IS NOT NULL) OR (target.[ActivityStatusYear] IS NOT NULL AND source.[ActivityStatusYear] IS NULL))
    ) THEN UPDATE SET
        [FacilityName] = source.[FacilityName],
        [FacilityOtherNames] = source.[FacilityOtherNames],
        [SubSiteName] = source.[SubSiteName],
        [SubSiteOtherNames] = source.[SubSiteOtherNames],
        [FacilityType] = source.[FacilityType],
        [PrimaryCommodity] = source.[PrimaryCommodity],
        [CommoditiesProducts] = source.[CommoditiesProducts],
        [FacilityEquipment] = source.[FacilityEquipment],
        [ActivityStatus] = source.[ActivityStatus],
        [Country] = source.[Country],
        [GadmLevel0Code] = source.[GadmLevel0Code],
        [GadmLevel1Code] = source.[GadmLevel1Code],
        [GadmLevel2Code] = source.[GadmLevel2Code],
        [GadmLevel3Code] = source.[GadmLevel3Code],
        [GadmLevel4Code] = source.[GadmLevel4Code],
        [LocationGeometry] = source.[LocationGeometry],
        [Comment] = source.[Comment],
        [SurfaceAreaSquareKilometers] = source.[SurfaceAreaSquareKilometers],
        [ConcessionAreaSquareKilometers] = source.[ConcessionAreaSquareKilometers],
        [ProductionStartYear] = source.[ProductionStartYear],
        [ProductionEndYear] = source.[ProductionEndYear],
        [ActivityStatusYear] = source.[ActivityStatusYear],
        [LastUpdateLoadStepID] = @LoadStepID,
        [LastUpdateTimestamp] = @Now
    WHEN NOT MATCHED BY TARGET THEN INSERT (
        [DimFacility_SK],
        [Facility_BK],
        [FacilityName],
        [FacilityOtherNames],
        [SubSiteName],
        [SubSiteOtherNames],
        [FacilityType],
        [PrimaryCommodity],
        [CommoditiesProducts],
        [FacilityEquipment],
        [ActivityStatus],
        [Country],
        [GadmLevel0Code],
        [GadmLevel1Code],
        [GadmLevel2Code],
        [GadmLevel3Code],
        [GadmLevel4Code],
        [LocationGeometry],
        [Comment],
        [SurfaceAreaSquareKilometers],
        [ConcessionAreaSquareKilometers],
        [ProductionStartYear],
        [ProductionEndYear],
        [ActivityStatusYear],
        [InsertLoadStepID],
        [InsertTimestamp],
        [LastUpdateLoadStepID],
        [LastUpdateTimestamp]
    ) VALUES (
        source.[NewKey],
        source.[Facility_BK],
        source.[FacilityName],
        source.[FacilityOtherNames],
        source.[SubSiteName],
        source.[SubSiteOtherNames],
        source.[FacilityType],
        source.[PrimaryCommodity],
        source.[CommoditiesProducts],
        source.[FacilityEquipment],
        source.[ActivityStatus],
        source.[Country],
        source.[GadmLevel0Code],
        source.[GadmLevel1Code],
        source.[GadmLevel2Code],
        source.[GadmLevel3Code],
        source.[GadmLevel4Code],
        source.[LocationGeometry],
        source.[Comment],
        source.[SurfaceAreaSquareKilometers],
        source.[ConcessionAreaSquareKilometers],
        source.[ProductionStartYear],
        source.[ProductionEndYear],
        source.[ActivityStatusYear],
        @LoadStepID,
        @Now,
        @LoadStepID,
        @Now
    );
END
GO
